/* Payroll Automation â€” shared app styles.
   Design system (see UC-003 guide Â§7.1 / EFAR shell): dark maroon top bar,
   red accent, white cards on a light neutral background, pill statuses.
   All colours live in the variables below â€” change them here, nowhere else. */

:root {
  --maroon: #4c1420;        /* top bar / sidebar */
  --maroon-soft: #63202f;   /* hover on maroon */
  --accent: #b3273e;        /* primary red accent */
  --accent-dark: #8f1f32;
  --bg: #f6f4f2;            /* app background */
  --surface: #ffffff;       /* cards */
  --border: #e3dedd;
  --text: #232125;
  --text-muted: #6f6a70;
  --good: #1e7d43;
  --good-bg: #e4f3ea;
  --warning: #92600a;
  --warning-bg: #fcf1dc;
  --critical: #a52333;
  --critical-bg: #fbe7ea;
  --shadow: rgba(35, 33, 37, 0.07) 0 2px 8px;
  --sans: system-ui, 'Segoe UI', Roboto, sans-serif;
  --mono: ui-monospace, Consolas, monospace;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font: 15px/1.5 var(--sans);
  color: var(--text);
  background: var(--bg);
}

h1, h2, h3 { color: var(--text); line-height: 1.25; }

a { color: var(--accent); }

/* â”€â”€ App shell â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.app-shell { min-height: 100vh; }

.topbar {
  background: var(--maroon);
  color: #fff;
  box-shadow: var(--shadow);
}

.topbar-inner {
  max-width: 1160px;
  margin: 0 auto;
  padding: 0.6rem 1.5rem;
}

.topbar-inner h1 { margin: 0.2rem 0; font-size: 1.25rem; color: #fff; }

.dashboard-nav { display: flex; gap: 0.4rem; flex-wrap: wrap; padding-top: 0; }

.nav-tab {
  background: transparent;
  color: rgba(255, 255, 255, 0.85);
  border: none;
  border-bottom: 3px solid transparent;
  padding: 0.55rem 0.9rem;
  font: inherit;
  font-size: 0.92rem;
  cursor: pointer;
  border-radius: 0;
}

.nav-tab:hover { background: var(--maroon-soft); color: #fff; }

.nav-tab-active {
  color: #fff;
  font-weight: 600;
  border-bottom-color: var(--accent);
}

.page {
  max-width: 1160px;
  margin: 0 auto;
  padding: 1.5rem;
}

.page-intro { color: var(--text-muted); margin-top: -0.4rem; }

.muted { color: var(--text-muted); }

/* â”€â”€ Cards â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow);
  padding: 1.1rem 1.3rem;
  margin-bottom: 1.2rem;
}

.card-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 0.6rem;
}

.card-header h2, .card-header h3 { margin: 0; font-size: 1.05rem; }

.card-count { color: var(--text-muted); font-size: 0.9rem; }

/* â”€â”€ Stat tiles â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 0.9rem;
  margin: 0.8rem 0;
}

.stat-tile {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 0.85rem 1rem;
}

.stat-label {
  margin: 0;
