.badge-warning { background: var(--warning-bg); color: var(--warning); }
.badge-critical { background: var(--critical-bg); color: var(--critical); }

/* â”€â”€ Banners â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.banner {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  border-radius: 8px;
  padding: 0.7rem 1rem;
  margin: 0.8rem 0;
  border: 1px solid var(--border);
  background: var(--surface);
}

.banner-icon { flex: none; }

.warning-banner { background: var(--warning-bg); border-color: #ecd9b0; color: var(--warning); }
.error-banner { background: var(--critical-bg); border-color: #efc4cb; color: var(--critical); }
.success-banner { background: var(--good-bg); border-color: #bfe0cc; color: var(--good); }

/* â”€â”€ Buttons & forms â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

button {
  font: inherit;
  font-size: 0.92rem;
  padding: 0.5rem 1rem;
  border-radius: 7px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

button:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }

button:disabled { opacity: 0.55; cursor: not-allowed; }

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  font-weight: 600;
}

button.primary:hover:not(:disabled) { background: var(--accent-dark); color: #fff; }

.button-row {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  flex-wrap: wrap;
  margin: 0.6rem 0;
}

.button-row-caption { color: var(--text-muted); font-size: 0.85rem; }

input, select, textarea {
  font: inherit;
  font-size: 0.92rem;
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: #fff;
  color: var(--text);
}

input:focus, select:focus, textarea:focus, button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

label { font-size: 0.85rem; color: var(--text-muted); }

.field-row {
  display: flex;
  gap: 0.9rem;
  flex-wrap: wrap;
  margin: 0.6rem 0;
}

.field-column { display: flex; flex-direction: column; gap: 0.25rem; flex: 1 1 180px; }

/* â”€â”€ Login card â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.login-card {
  max-width: 420px;
  margin: 2.5rem auto;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow);
  padding: 1.4rem 1.6rem;
}

.login-card h2 { margin-top: 0; }

.login-switch {
  background: none;
  border: none;
  padding: 0;
  color: var(--accent);
  text-decoration: underline;
  font-size: 0.88rem;
}

/* â”€â”€ Tables â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.table-scroll { overflow-x: auto; }

table { border-collapse: collapse; width: 100%; font-size: 0.92rem; }

th, td {
  text-align: left;
  padding: 0.55rem 0.75rem;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

th {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  background: #faf8f7;
}

tbody tr:hover { background: #faf6f4; }

.numeric { text-align: right; font-variant-numeric: tabular-nums; }

.line-note { font-size: 0.84rem; color: var(--warning); max-width: 34ch; white-space: normal; }

/* â”€â”€ Lists (exceptions, sync history) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.exception-list, .history-list { list-style: none; margin: 0; padding: 0; }

.exception-item, .history-item {
  display: flex;
  align-items: baseline;
  gap: 0.7rem;
  flex-wrap: wrap;
  padding: 0.55rem 0.2rem;
  border-bottom: 1px solid var(--border);
}

.exception-item-critical { background: var(--critical-bg); }

.exception-name { font-weight: 600; }

.exception-meta, .history-time { color: var(--text-muted); font-size: 0.85rem; }

.history-detail { flex: 1 1 auto; }

/* â”€â”€ In-page tabs (Payroll Lines | Adjustments | ...) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.tab-row {
  display: flex;
  gap: 0.2rem;
  border-bottom: 2px solid var(--border);
  margin: 1rem 0 1.1rem;
}

.tab {
  border: none;
  background: transparent;
  border-radius: 6px 6px 0 0;
  padding: 0.5rem 1rem;
  margin-bottom: -2px;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  font-weight: 500;
}

.tab:hover:not(:disabled) { color: var(--accent); border-bottom-color: var(--border); }

.tab-active,
.tab-active:hover:not(:disabled) {
  color: var(--accent);
  font-weight: 650;
  border-bottom-color: var(--accent);
}

